const NO_DILEMMA: SpellMode = SpellMode {
    text: "Choose nothing",
    targets: TargetPlan::NONE,
    program: &[],
};
const A_DILEMMA: SpellMode = SpellMode {
    text: "Choose this mode",
    targets: TargetPlan::NONE,
    program: &[],
};
const DILEMMA_FIXTURE: CardRules = CardRules {
    effect: Effect::Modal(&[NO_DILEMMA, A_DILEMMA]),
    mode_counts: Some(&[0, 1]),
    ..CardRules::EMPTY
};

#[test]
fn garak_taxes_each_chosen_dilemma_once_and_keeps_menace() {
    let opt = Card::from_name("Opt").unwrap();
    let _fixture = fixture_rules::activate(&[(opt, &DILEMMA_FIXTURE)]);
    for player in [Player::P0, Player::P1] {
        for (mode, triggers) in [(0, 0), (1, 1)] {
            let mut game = scenario(player);
            let garak = owned(
                &mut game,
                player,
                "Elim Garak, Simple Tailor",
                Zone::Battlefield,
            );
            assert_eq!(stats(&game, garak), (3, 3));
            assert!(game.keywords(garak).contains(Keywords::MENACE));
            let spell = spawn(&mut game, player, opt, Zone::Hand);
            act(&mut game, Action::AnnounceCast { card: spell });
            reject(&mut game, Action::ChooseMode { mode: 9 });
            act(&mut game, Action::ChooseMode { mode });
            pay(&mut game);
            drain(&mut game);
            assert_eq!(
                game.state.players[player.index()].life,
                20 + 2 * i128::from(triggers)
            );
            assert_eq!(
                game.state.players[player.other().index()].life,
                20 - 2 * i128::from(triggers)
            );
            assert_eq!(
                game.state.players[player.index()].dilemmas_faced_this_turn,
                triggers
            );
            let checkpoint = game.snapshot();
            let mut branch = game.clone();
            branch.restore(&checkpoint).unwrap();
            assert_eq!(branch.snapshot(), checkpoint);
        }
    }
}

#[test]
fn federation_probe_entry_modes_apply_a_targeted_boost_or_surveil() {
    for mode in [0, 1] {
        let player = Player::P0;
        let mut game = scenario(player);
        let target = put(&mut game, player.other(), "Bear Cub", Zone::Battlefield);
        let top = put(&mut game, player, "Island", Zone::Library);
        let probe = owned(&mut game, player, "Federation Probe", Zone::Hand);
        cast(&mut game, probe, None);
        for _ in 0..12 {
            if game.legal_actions().contains(&Action::ChooseMode { mode }) {
                break;
            }
            choose(&mut game, |a| {
                matches!(a, Action::Pass | Action::PutTrigger { .. })
            });
        }
        assert_eq!(stats(&game, probe), (1, 1));
        assert!(game.keywords(probe).contains(Keywords::FLYING));
        reject(&mut game, Action::ChooseMode { mode: 9 });
        act(&mut game, Action::ChooseMode { mode });
        if mode == 0 {
            act(
                &mut game,
                Action::ChooseTarget {
                    target: Target::Card(target),
                },
            );
            drain(&mut game);
            assert_eq!(stats(&game, target), (3, 3));
        } else {
            for _ in 0..8 {
                if game.observe(player).library_choice.is_some() {
                    break;
                }
                choose(&mut game, |a| {
                    matches!(a, Action::Pass | Action::PutTrigger { .. })
                });
            }
            assert!(game.observe(player).library_choice.unwrap().surveil);
            act(
                &mut game,
                Action::ArrangeLibrary {
                    card: top,
                    destination: LibraryDestination::Graveyard,
                },
            );
            drain(&mut game);
            assert_eq!(game.object_view(top).zone, Zone::Graveyard);
            assert_eq!(stats(&game, target), (2, 2));
        }
    }
}

#[test]
fn holographic_crew_recovers_only_own_spacecraft_or_surveils_two() {
    for mode in [0, 1] {
        let player = Player::P0;
        let mut game = scenario(player);
        let own_ship = owned(&mut game, player, "Enterprise NX-01", Zone::Graveyard);
        let other_ship = owned(
            &mut game,
            player.other(),
            "Enterprise NX-01",
            Zone::Graveyard,
        );
        let bow = put(&mut game, player, "Short Bow", Zone::Graveyard);
        let cards = [
            put(&mut game, player, "Island", Zone::Library),
            put(&mut game, player, "Forest", Zone::Library),
        ];
        let crew = owned(&mut game, player, "Emergency Holographic Crew", Zone::Hand);
        cast(&mut game, crew, None);
        for _ in 0..12 {
            if game.legal_actions().contains(&Action::ChooseMode { mode }) {
                break;
            }
            choose(&mut game, |a| {
                matches!(a, Action::Pass | Action::PutTrigger { .. })
            });
        }
        assert_eq!(stats(&game, crew), (3, 4));
        act(&mut game, Action::ChooseMode { mode });
        if mode == 0 {
            reject(
                &mut game,
                Action::ChooseTarget {
                    target: Target::Card(bow),
                },
            );
            reject(
                &mut game,
                Action::ChooseTarget {
                    target: Target::Card(other_ship),
                },
            );
            act(
                &mut game,
                Action::ChooseTarget {
                    target: Target::Card(own_ship),
                },
            );
            drain(&mut game);
            assert_eq!(game.object_view(own_ship).zone, Zone::Hand);
        } else {
            for _ in 0..8 {
                if game.observe(player).library_choice.is_some() {
                    break;
                }
                choose(&mut game, |a| {
                    matches!(a, Action::Pass | Action::PutTrigger { .. })
                });
            }
            assert!(game.observe(player).library_choice.unwrap().surveil);
            for card in cards {
                act(
                    &mut game,
                    Action::ArrangeLibrary {
                        card,
                        destination: LibraryDestination::Graveyard,
                    },
                );
            }
            drain(&mut game);
            for card in cards {
                assert_eq!(game.object_view(card).zone, Zone::Graveyard);
            }
        }
        assert_eq!(game.object_view(other_ship).zone, Zone::Graveyard);
    }
}

#[test]
fn federation_outpost_uses_entry_tap_status_for_modes_and_makes_white_mana() {
    for (other_lands, mode) in [(0, None), (2, Some(0)), (2, Some(1))] {
        let player = Player::P0;
        let mut game = scenario(player);
        for _ in 0..other_lands {
            put(&mut game, player, "Forest", Zone::Battlefield);
        }
        let top = put(&mut game, player, "Island", Zone::Library);
        let outpost = owned(&mut game, player, "Federation Outpost", Zone::Hand);
        act(&mut game, Action::PlayLand { card: outpost });
        assert_eq!(game.object_view(outpost).tapped, mode.is_none());
        if let Some(mode) = mode {
            for _ in 0..8 {
                if game.legal_actions().contains(&Action::ChooseMode { mode }) {
                    break;
                }
                choose(&mut game, |a| {
                    matches!(a, Action::Pass | Action::PutTrigger { .. })
                });
            }
            act(&mut game, Action::ChooseMode { mode });
            if mode == 1 {
                for _ in 0..8 {
                    if game.observe(player).library_choice.is_some() {
                        break;
                    }
                    choose(&mut game, |a| {
                        matches!(a, Action::Pass | Action::PutTrigger { .. })
                    });
                }
                act(
                    &mut game,
                    Action::ArrangeLibrary {
                        card: top,
                        destination: LibraryDestination::Graveyard,
                    },
                );
            }
            drain(&mut game);
            assert_eq!(
                game.state.players[player.index()].life,
                if mode == 0 { 22 } else { 20 }
            );
            assert_eq!(
                game.object_view(top).zone,
                if mode == 1 {
                    Zone::Graveyard
                } else {
                    Zone::Library
                }
            );
        } else {
            drain(&mut game);
            assert_eq!(game.state.players[player.index()].life, 20);
            game.untap_objects(&[outpost], untap_rules::UntapCause::Effect);
            game.prepare_triggers();
            assert!(game.state.stack.is_empty());
        }
        game.state.players[player.index()].mana = [0; 6];
        act(
            &mut game,
            Action::ActivateMana {
                card: outpost,
                ability: 0,
                payment: [0; 6],
                counter_payment: Counters::default(),
                production: [1, 0, 0, 0, 0, 0],
            },
        );
        assert_eq!(game.state.players[player.index()].mana, [1, 0, 0, 0, 0, 0]);
    }
}

#[test]
fn encounter_unknown_chooses_next_turn_play_or_damage_to_every_creature_and_player() {
    for mode in [0, 1] {
        let player = Player::P0;
        let mut game = scenario(player);
        let own = put(&mut game, player, "Bear Cub", Zone::Battlefield);
        let other = put(&mut game, player.other(), "Bear Cub", Zone::Battlefield);
        let first = put(&mut game, player, "Forest", Zone::Library);
        let second = put(&mut game, player, "Island", Zone::Library);
        let spell = owned(&mut game, player, "Encounter the Unknown", Zone::Hand);
        act(&mut game, Action::AnnounceCast { card: spell });
        reject(&mut game, Action::ChooseMode { mode: 8 });
        act(&mut game, Action::ChooseMode { mode });
        pay(&mut game);
        drain(&mut game);
        if mode == 0 {
            assert_eq!(game.object_view(first).zone, Zone::Exile);
            assert_eq!(game.object_view(second).zone, Zone::Exile);
            let permissions = game.observe(player).exile_permissions;
            assert_eq!(permissions.len(), 2);
            for row in permissions {
                assert_eq!(row.expiry, ExilePlayExpiry::EndOfNextTurn);
                assert!(!row.cast_only);
            }
            assert_eq!(game.object_view(own).zone, Zone::Battlefield);
            assert_eq!(game.object_view(other).zone, Zone::Battlefield);
            assert_eq!(game.state.players[player.index()].life, 20);
        } else {
            assert_eq!(game.object_view(own).zone, Zone::Graveyard);
            assert_eq!(game.object_view(other).zone, Zone::Graveyard);
            assert_eq!(game.state.players[player.index()].life, 18);
            assert_eq!(game.state.players[player.other().index()].life, 18);
            assert_eq!(game.object_view(first).zone, Zone::Library);
        }
    }
}

#[test]
fn federation_resupply_searches_exact_subtype_union_and_has_beam_route() {
    for allowed_name in ["Sheltered by Ghosts", "Short Bow", "Enterprise NX-01"] {
        let player = Player::P0;
        let mut game = scenario(player);
        let allowed = owned(&mut game, player, allowed_name, Zone::Library);
        let excluded = put(&mut game, player, "Bear Cub", Zone::Library);
        let spell = owned(&mut game, player, "Federation Resupply", Zone::Hand);
        cast(&mut game, spell, None);
        for _ in 0..8 {
            if game
                .legal_actions()
                .iter()
                .any(|a| matches!(a, Action::ChooseSearch { .. }))
            {
                break;
            }
            choose(&mut game, |a| {
                matches!(a, Action::Pass | Action::PutTrigger { .. })
            });
        }
        reject(&mut game, Action::ChooseSearch { card: excluded });
        act(&mut game, Action::ChooseSearch { card: allowed });
        act(&mut game, Action::FinishSearch);
        drain(&mut game);
        assert_eq!(game.object_view(allowed).zone, Zone::Hand);
        assert_eq!(game.object_view(spell).zone, Zone::Graveyard);
        let second_target = put(&mut game, player, "Short Bow", Zone::Library);
        let returner = put(&mut game, player, "Bear Cub", Zone::Battlefield);
        let beam = Action::AnnounceBeamMeUp {
            card: spell,
            face: CastFace::Normal,
            cost: ManaCost {
                colored: [1, 0, 0, 0, 0, 0],
                generic: 3,
            },
            flash_surcharge: false,
            provider: None,
        };
        assert!(game.legal_actions().contains(&beam));
        act(&mut game, beam);
        act(&mut game, Action::BeginOrderedCosts);
        let clauses = game.observe(player).cast_costs.unwrap().clauses;
        let mana = clauses
            .iter()
            .position(|row| !row.paid && row.clause == CastCostClause::Mana)
            .unwrap() as u16;
        act(&mut game, Action::ChooseCastCost { clause: mana });
        pay(&mut game);
        let clauses = game.observe(player).cast_costs.unwrap().clauses;
        let returned = clauses
            .iter()
            .position(|row| !row.paid && matches!(row.clause, CastCostClause::BeamMeUpReturn(_, _)))
            .unwrap() as u16;
        act(&mut game, Action::ChooseCastCost { clause: returned });
        let return_ref = game.object_ref(returner);
        act(&mut game, Action::PayBeamMeUpReturn { object: return_ref });
        for _ in 0..8 {
            if game
                .legal_actions()
                .iter()
                .any(|a| matches!(a, Action::ChooseSearch { .. }))
            {
                break;
            }
            choose(&mut game, |a| {
                matches!(a, Action::Pass | Action::PutTrigger { .. })
            });
        }
        assert_eq!(game.object_view(returner).zone, Zone::Hand);
        act(
            &mut game,
            Action::ChooseSearch {
                card: second_target,
            },
        );
        act(&mut game, Action::FinishSearch);
        drain(&mut game);
        assert_eq!(game.object_view(second_target).zone, Zone::Hand);
        assert_eq!(game.object_view(spell).zone, Zone::Exile);
    }
}

#[test]
