#[test]
fn gaseous_anomaly_sacrifices_as_cost_then_draws_and_makes_tapped_planet() {
    let player = Player::P0;
    let mut mana_game = scenario(player);
    let mana_source = owned(&mut mana_game, player, "Gaseous Anomaly", Zone::Battlefield);
    mana_game.state.players[player.index()].mana = [0; 6];
    act(
        &mut mana_game,
        Action::ActivateMana {
            card: mana_source,
            ability: 0,
            payment: [0; 6],
            counter_payment: Counters::default(),
            production: [0, 0, 0, 0, 0, 1],
        },
    );
    assert_eq!(
        mana_game.state.players[player.index()].mana,
        [0, 0, 0, 0, 0, 1]
    );

    let mut game = scenario(player);
    let anomaly = owned(&mut game, player, "Gaseous Anomaly", Zone::Battlefield);
    let cards = [
        put(&mut game, player, "Island", Zone::Library),
        put(&mut game, player, "Forest", Zone::Library),
    ];
    game.state.players[player.index()].mana = [0, 6, 0, 0, 0, 0];
    let first_new = game.state.objects.len();
    act(
        &mut game,
        Action::AnnounceActivate {
            card: anomaly,
            ability: 1,
            counter_payment: Counters::default(),
        },
    );
    pay(&mut game);
    assert_eq!(game.object_view(anomaly).zone, Zone::Graveyard);
    drain(&mut game);
    assert_eq!(game.state.players[player.index()].cards_drawn_this_turn, 2);
    for card in cards {
        assert_eq!(game.object_view(card).zone, Zone::Hand);
    }
    let planets: Vec<_> = (first_new..game.state.objects.len())
        .map(|id| id as CardId)
        .filter(|&id| game.object_view(id).zone == Zone::Battlefield)
        .collect();
    assert_eq!(planets.len(), 1);
    let planet = planets[0];
    assert_eq!(game.object_view(planet).card, Card::from_catalogue_id(6009));
    assert!(game.object_view(planet).tapped);
    game.untap_objects(&[planet], untap_rules::UntapCause::Effect);
    game.state.players[player.index()].mana = [0; 6];
    act(
        &mut game,
        Action::ActivateMana {
            card: planet,
            ability: 0,
            payment: [0; 6],
            counter_payment: Counters::default(),
            production: [1, 0, 0, 0, 0, 0],
        },
    );
    assert_eq!(game.state.players[player.index()].mana, [1, 0, 0, 0, 0, 0]);
}

#[test]
fn jett_reno_grows_per_dilemma_and_tap_checks_live_power_for_draw() {
    let opt = Card::from_name("Opt").unwrap();
    let _fixture = fixture_rules::activate(&[(opt, &DILEMMA_FIXTURE)]);
    let player = Player::P0;
    let mut low = scenario(player);
    let jett = owned(
        &mut low,
        player,
        "Jett Reno, Problem Solver",
        Zone::Battlefield,
    );
    let top = put(&mut low, player, "Island", Zone::Library);
    low.tap_objects(&[jett]);
    for _ in 0..8 {
        if low.observe(player).library_choice.is_some() {
            break;
        }
        choose(&mut low, |a| {
            matches!(a, Action::Pass | Action::PutTrigger { .. })
        });
    }
    assert!(low.observe(player).library_choice.unwrap().surveil);
    act(
        &mut low,
        Action::ArrangeLibrary {
            card: top,
            destination: LibraryDestination::Graveyard,
        },
    );
    drain(&mut low);
    assert_eq!(low.state.players[player.index()].cards_drawn_this_turn, 0);
    assert_eq!(low.object_view(top).zone, Zone::Graveyard);

    let mut high = scenario(player);
    let jett = owned(
        &mut high,
        player,
        "Jett Reno, Problem Solver",
        Zone::Battlefield,
    );
    for _ in 0..3 {
        let spell = spawn(&mut high, player, opt, Zone::Hand);
        act(&mut high, Action::AnnounceCast { card: spell });
        act(&mut high, Action::ChooseMode { mode: 1 });
        pay(&mut high);
        drain(&mut high);
    }
    assert_eq!(high.counter_count(jett, CounterKind::PlusOne), 3);
    assert_eq!(stats(&high, jett), (4, 5));
    let draw = put(&mut high, player, "Forest", Zone::Library);
    high.tap_objects(&[jett]);
    drain(&mut high);
    assert_eq!(high.object_view(draw).zone, Zone::Hand);
    assert_eq!(high.state.players[player.index()].cards_drawn_this_turn, 1);

    // The tap trigger uses departure LKI when Jett leaves before it resolves.
    let mut departed = scenario(player);
    let jett = owned(
        &mut departed,
        player,
        "Jett Reno, Problem Solver",
        Zone::Battlefield,
    );
    for _ in 0..3 {
        let spell = spawn(&mut departed, player, opt, Zone::Hand);
        act(&mut departed, Action::AnnounceCast { card: spell });
        act(&mut departed, Action::ChooseMode { mode: 1 });
        pay(&mut departed);
        drain(&mut departed);
    }
    let draw = put(&mut departed, player, "Island", Zone::Library);
    departed.tap_objects(&[jett]);
    departed.move_object(jett, Zone::Graveyard);
    drain(&mut departed);
    assert_eq!(departed.object_view(draw).zone, Zone::Hand);
    assert_eq!(
        departed.state.players[player.index()].cards_drawn_this_turn,
        1
    );
}

